// Acepta "12" o "#12" en id; si no hay id válido se busca por texto.
const { id, texto } = $input.first().json;
const limpio = String(id ?? '').replace('#', '').trim();
return [{ json: { id: /^\d+$/.test(limpio) ? Number(limpio) : null, texto: String(texto ?? '') } }];

// 404 → ninguno. Cualquier otro error de la app (401, 500) se lanza: no es "no encontrado".
const r = $input.first().json;
if (r.statusCode === 404) return [{ json: { resultado: 'ninguno', candidatos: [] } }];
if (r.statusCode !== 200) throw new Error(`La tienda respondió ${r.statusCode}: ${JSON.stringify(r.body)}`);
const a = r.body;
// Solo apartados que pueden recibir abonos.
if (a.estado !== 'activo') return [{ json: { resultado: 'ninguno', candidatos: [] } }];
const { id, cliente, producto, talla, precio, abonado, pendiente, fecha_limite, estado } = a;
return [{ json: { resultado: 'unico', candidatos: [{ id, cliente, producto, talla, precio, abonado, pendiente, fecha_limite, estado }] } }];

// Minúsculas, sin acentos y sin puntuación.
function normalizar(s) {
  return String(s ?? '')
    .normalize('NFD').replace(/\p{M}/gu, '')
    .toLowerCase().replace(/[^a-z0-9#]+/g, ' ').trim();
}

const PARTICULAS = new Set(['de', 'del', 'la', 'las', 'los', 'el', 'y']);

// Trozos del texto que pueden ser parte de un nombre: 3 letras o más, sin partículas.
function trozos(s) {
  return [...new Set(normalizar(s).split(' ')
    .filter(t => /^[a-z]{3,}$/.test(t) && !PARTICULAS.has(t)))];
}

// Un trozo coincide con una palabra del nombre si es igual o, con 4 letras o más, su comienzo.
function coincide(trozo, palabra) {
  return palabra === trozo || (trozo.length >= 4 && palabra.startsWith(trozo));
}

function puntuar(trozosTexto, cliente) {
  const palabras = normalizar(cliente).split(' ');
  return trozosTexto.filter(t => palabras.some(p => coincide(t, p))).length;
}

// Número de apartado escrito en el texto: "#12", "apartado 2", "ap. 3", "nº 4".
function pistaId(s) {
  const m = normalizar(s).match(/(?:#|\bapartado\s+|\bap\s+|\bn[ou]?\s+)(\d+)\b/);
  return m ? Number(m[1]) : null;
}

const resumen = a => ({
  id: a.id, cliente: a.cliente, producto: a.producto, talla: a.talla, precio: a.precio,
  abonado: a.abonado, pendiente: a.pendiente, fecha_limite: a.fecha_limite, estado: a.estado,
});

function buscar(texto, apartados) {
  const activos = apartados.filter(a => a.estado === 'activo');
  const t = trozos(texto);
  const puntuados = activos.map(a => ({ a, puntos: puntuar(t, a.cliente) }))
    .filter(x => x.puntos > 0);

  // El número solo cuenta si ese apartado también coincide con algún trozo del nombre.
  const id = pistaId(texto);
  const porId = puntuados.find(x => x.a.id === id);
  let elegidos;
  if (porId) {
    elegidos = [porId.a];
  } else {
    const max = Math.max(0, ...puntuados.map(x => x.puntos));
    elegidos = puntuados.filter(x => x.puntos === max).map(x => x.a);
  }
  const resultado = elegidos.length === 0 ? 'ninguno' : elegidos.length === 1 ? 'unico' : 'varios';
  return { resultado, candidatos: elegidos.map(resumen) };
}

const texto = $('Preparar entrada').first().json.texto;
// "Apartados activos" saca un item vacío si no hay ninguno (alwaysOutputData).
const apartados = $input.all().map(i => i.json).filter(a => a.id !== undefined);
return [{ json: buscar(texto, apartados) }];
